(()=>{'use strict';
const C=window.CashewCore,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',transactions:'M3 5h18v14H3z M7 9h.01M17 15h.01 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',budget:'M12 3v9h9M9 3a9 9 0 1 0 12 12M15 3a7 7 0 0 1 6 6h-6z',calendar:'M5 5h14a2 2 0 0 1 2 2v13H3V7a2 2 0 0 1 2-2M7 3v4m10-4v4M3 10h18M7 14h3m4 0h3m-10 3h3',chart:'M4 3v18h17M7 15l4-5 4 3 5-8',target:'M21 12a9 9 0 1 1-9-9M17 12a5 5 0 1 1-5-5m0 5 9-9m-5 0h5v5',wallet:'M3 6h17v14H3zM3 6V4h14v2M15 10h6v6h-6zM17 13h.01',bank:'m3 8 9-5 9 5H3m0 13h18M5 10v8m5-8v8m4-8v8m5-8v8',cash:'M2 6h20v13H2zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0M5 9v.01m14 6v.01',categories:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm14 0 4 7h-8z',settings:'m9 3-1 3-3 1 1 3-2 2 2 2-1 3 3 1 1 3h6l1-3 3-1-1-3 2-2-2-2 1-3-3-1-1-3z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0m-1 5 6 6',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',left:'m15 5-7 7 7 7',right:'m9 5 7 7-7 7',down:'m5 9 7 7 7-7',up:'m5 15 7-7 7 7',arrowUp:'M12 20V4m-7 7 7-7 7 7',arrowDown:'M12 4v16m-7-7 7 7 7-7',transfer:'M3 7h17m-4-4 4 4-4 4M21 17H4m4-4-4 4 4 4',check:'m4 12 5 5L20 6',dots:'M5 12h.01M12 12h.01M19 12h.01',edit:'m4 16 12-12 4 4L8 20H4zm10-10 4 4',trash:'M3 6h18M5 6l1 15h12l1-15M9 6V3h6v3M10 10v7m4-7v7',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',repeat:'M4 10V5h13l3 3m0 6v5H7l-3-3m0-6L1 7m3 3 3-3m13 7-3 3m3-3 3 3',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 6v6l4 2',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zm5 3h4',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12',restaurant:'M5 3v7m4-7v7m-6-7v5a4 4 0 0 0 8 0V3M7 12v9M18 3c-4 3-4 8 0 8V3v18',basket:'m3 9 2 12h14l2-12H3M8 9l4-6 4 6m-8 4 1 5m6-5-1 5',bag:'M4 8h16l1 13H3zM8 8V6a4 4 0 0 1 8 0v2',car:'m4 10 2-6h12l2 6M3 10h18v8H3zM5 18v3m14-3v3M6 13h2m8 0h2',game:'M6 6h12l4 12-4 2-4-5h-4l-4 5-4-2zM7 8v5m-2-2h4m6-2h.01m3 3h.01',heart:'M12 21 3 12a6 6 0 0 1 9-8 6 6 0 0 1 9 8z',work:'M3 7h18v14H3zM8 7V3h8v4M3 12l9 3 9-3M12 12v5',plane:'m21 3-6 18-3-8-9-4zM12 13l9-10',book:'M12 5C8 2 4 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-4-2-7-1-10 1zm0 0v16',coffee:'M4 4h12v10a6 6 0 0 1-12 0zM16 5h2a4 4 0 0 1 0 8h-2M2 21h18',gift:'M3 8h18v5H3zm2 5v8h14v-8M12 8v13M12 8C2 8 5-1 9 4zm0 0c10 0 7-9 3-4z',phone:'M6 2h12v20H6zM10 18h4',pet:'M8 13c-6 7 0 10 4 6 4 4 10 1 4-6zM5 5v3m5-6v4m4-4v4m5-1v3',cloud:'M7 18h11a5 5 0 0 0 0-10 7 7 0 0 0-13 2 4 4 0 0 0 2 8',link:'m10 14 4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',split:'M12 21V12M12 12 5 5M12 12l7-7M2 5h6M5 2v6M16 5h6m-3-3v6',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 10v7m0-10v.01',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6zM8 12l3 3 5-6'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${Object.hasOwn(paths,n)?paths[n]:paths.dots}"/></svg>`;
const I=(name,action,label,extra='')=>`<button type="button" class="icon-button" data-action="${action}" title="${esc(label)}" aria-label="${esc(label)}" ${extra}>${icon(name)}</button>`;
let storage;try{storage=window.CASHEW_CONFIG?.storageAdapter||new C.LocalAdapter(localStorage);}catch(e){$('#app').textContent='浏览器禁止本地存储，请通过 localhost 打开。';return;}
let data,loadError;try{data=storage.load();}catch(e){loadError=e;data=C.defaults();}
let page='home',selectedAccount='',month=C.iso().slice(0,7),homeType='expense',statsType='expense',query='',filters={},selected=new Set(),batch=false,toastTimer,modalReturnFocus,syncVersion=null;
let attachments=[];
const t=(zh,en)=>data.settings.language==='en'?en:zh;
const labels={home:['首页','Home'],transactions:['交易','Transactions'],budgets:['预算','Budgets'],recurring:['订阅与周期','Subscriptions'],analysis:['全部支出','All spending'],goals:['目标','Goals'],debts:['债权与债务','Credit & debts'],accounts:['账户','Accounts'],categories:['分类','Categories'],split:['账单分摊','Bill splitter'],settings:['设置','Settings']};
const navIcons={home:'home',transactions:'transactions',budgets:'budget',recurring:'calendar',analysis:'chart',goals:'target',debts:'transfer',accounts:'wallet',categories:'categories',split:'split',settings:'settings'};
const name=p=>t(...labels[p]);
const fmt=(n,c=data.settings.currency)=>new Intl.NumberFormat(data.settings.language==='en'?'en-US':'zh-CN',{style:'currency',currency:c,minimumFractionDigits:2,maximumFractionDigits:2}).format(n/100);
const num=n=>(n/100).toFixed(2),dateLabel=s=>new Intl.DateTimeFormat(data.settings.language==='en'?'en-GB':'zh-CN',{month:'short',day:'numeric',weekday:'short'}).format(C.parseDate(s));
const mLabel=()=>new Intl.DateTimeFormat(data.settings.language==='en'?'en-GB':'zh-CN',{year:'numeric',month:'long'}).format(C.parseDate(month+'-01'));
const acc=id=>data.accounts.find(a=>a.id===id),cat=id=>data.categories.find(c=>c.id===id),monthPeriod=()=>C.period('monthly',month+'-01');
const btn=(label,action,ico='',cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
function notify(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function persist(fn,message,recovery=false){const next=structuredClone(data);try{if(loadError)throw Error(t('请先恢复有效备份','Restore a valid backup first'));const current=recovery?data:storage.load();if(current.updatedAt!==data.updatedAt||current.revision!==data.revision)throw Error(t('另一个标签页修改了账本，请刷新后再试','Ledger changed in another tab. Reload before retrying.'));fn(next);next.revision=(data.revision||0)+1;next.updatedAt=Date.now();C.validate(next);storage.save(next);data=next;render();if(message)notify(message);return true;}catch(e){showError(e);return false;}}
function showError(e){const node=$('#form-error');if(node)node.textContent=e.message||String(e);else notify(e.message||String(e));}
function applyTheme(){const theme=data.settings.theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):data.settings.theme;document.documentElement.dataset.theme=theme;document.documentElement.style.setProperty('--accent',data.settings.accent);document.documentElement.lang=data.settings.language==='en'?'en':'zh-CN';}
function nav(p){page=labels[p]?p:'home';selected.clear();batch=false;location.hash=page;render();window.scrollTo(0,0);}
function modal(title,body,wide=false){modalReturnFocus=document.activeElement;const el=$('#modal');el.className=wide?'wide':'';el.innerHTML=`<div class="modal-head"><h2>${title}</h2>${I('close','close',t('关闭','Close'))}</div>${body}`;if(!el.open)el.showModal();}
function close(){if($('#modal').open)$('#modal').close();modalReturnFocus?.focus?.();}
const empty=(title,desc,action,label)=>`<div class="empty">${icon('wallet')}<h3>${title}</h3><p>${desc}</p>${action?btn(label,action,'plus','small'):''}</div>`;
const field=(label,html,full=false)=>`<label class="field ${full?'full':''}"><span>${label}</span>${html}</label>`;
const input=(n,v='',type='text',attrs='')=>`<input name="${esc(n)}" type="${type}" value="${esc(v)}" ${attrs}>`;
const options=(rows,val)=>rows.map(([v,l])=>`<option value="${esc(v)}" ${v===val?'selected':''}>${esc(l)}</option>`).join('');
const select=(n,rows,val,attrs='')=>`<select name="${n}" ${attrs}>${options(rows,val)}</select>`;
const currencies=()=>Object.keys(data.settings.rates).map(x=>[x,x]);
const budgetDate=()=>month===C.iso().slice(0,7)?C.iso():month+'-01';
const accountOptions=()=>data.accounts.map(a=>[a.id,a.name+' · '+a.currency]);
const categoryOptions=()=>data.categories.map(c=>[c.id,c.name]);
const periods=()=>[['monthly',t('每月','Monthly')],['weekly',t('每周','Weekly')],['daily',t('每天','Daily')],['yearly',t('每年','Yearly')],['custom',t('自定义','Custom')]];
const checkOptions=(n,rows,values=[])=>`<div class="check-group">${rows.map(([id,l])=>`<label class="check-label"><input type="checkbox" name="${n}" value="${esc(id)}" ${values.includes(id)?'checked':''}>${esc(l)}</label>`).join('')}</div>`;
const formFooter=(save=t('保存','Save'))=>`<p id="form-error" class="error" role="alert"></p><div class="modal-footer">${btn(t('取消','Cancel'),'close','','plain')}<button class="btn primary" type="submit">${icon('check')}${save}</button></div>`;
function render(){applyTheme();const now=new Date();document.title='Cashew · '+name(page);const overdue=data.transactions.filter(x=>x.status==='pending'&&x.date<=C.iso()).length+data.recurring.filter(r=>r.active&&r.next<=C.iso()).length;
$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><img src="assets/icon.png" alt="Cashew">Cashew</div><div class="clock"><strong>${now.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</strong><span>${now.toLocaleDateString(data.settings.language==='en'?'en-GB':'zh-CN',{weekday:'long',month:'short',day:'numeric'})}</span></div><nav aria-label="${t('主导航','Main navigation')}">${Object.keys(labels).map(p=>`<button class="nav-button ${page===p?'active':''}" data-nav="${p}" ${page===p?'aria-current="page"':''}>${icon(navIcons[p])}<span>${name(p)}</span></button>`).join('')}</nav><div class="foot"><span><i class="status-dot"></i>${t('本地模式','On this device')}</span>${I('moon','theme',t('切换主题','Toggle theme'))}</div></aside><main class="main"><header class="page-header"><div><div class="eyebrow">${page==='home'?(data.settings.name?esc(data.settings.name)+' · ':'')+t('让每一笔，都心中有数','A little clarity, every day'):'CASHEW'}</div><h1>${name(page)}</h1></div><div class="header-actions">${data.demo?'<span class="pill demo">'+t('示例数据','Demo data')+'</span>':''}${page==='home'||page==='analysis'?`<div class="row desktop-only">${monthSwitcher()}</div>`:''}${I('search','search',t('搜索交易','Search transactions'))}${I('bell','notifications',t('待办提醒','Upcoming reminders'),overdue?'data-count="'+overdue+'"':'')}${I('settings','settings',t('设置','Settings'))}</div></header>${loadError?'<div class="error">'+t('保存的数据读取失败。为保护原数据，已暂停写入，请先导出原始备份。','Saved data could not be read. Export your raw backup before continuing.')+'</div>':''}${renderPage()}</main><button class="fab" data-action="add-tx" aria-label="${t('新增交易','Add transaction')}">${icon('plus')}<span class="fab-label">${t('记一笔','Add transaction')}</span></button><nav class="mobile-nav" aria-label="${t('底部导航','Mobile navigation')}">${['home','transactions','budgets','goals'].map(p=>`<button data-nav="${p}" class="${page===p?'active':''}"><span>${icon(navIcons[p])}</span>${name(p)}</button>`).join('')}<button data-action="more" class="${!['home','transactions','budgets','goals'].includes(page)?'active':''}"><span>${icon('dots')}</span>${t('更多','More')}</button></nav>`;
if(loadError){document.querySelectorAll('[data-action]').forEach(b=>b.disabled=true);$('#app').insertAdjacentHTML('beforeend',`<div style="position:fixed;inset:20% 15%;z-index:60;background:var(--surface);padding:30px;border-radius:24px"><h2>${t('本地数据读取失败','Unable to read saved data')}</h2><p class="info">${esc(loadError.message)}</p>${btn(t('导出原始数据','Export raw data'),'raw-backup')}${btn(t('导入 JSON 备份','Import JSON backup'),'import-json')}</div>`);}
}
function monthSwitcher(){return `${I('left','prev-month',t('上个月','Previous month'))}<button class="btn plain small" data-action="month">${mLabel()}</button>${I('right','next-month',t('下个月','Next month'))}`;}
function renderPage(){switch(page){case'home':return home();case'transactions':return transactionPage();case'budgets':return budgetPage();case'analysis':return analysis();case'accounts':return accounts();case'categories':return categories();case'goals':return goals();case'recurring':return recurring();case'debts':return debts();case'split':return splitter();case'settings':return settings();}}
function accountStrip(){return `<div class="accounts-strip"><button class="account-chip ${!selectedAccount?'active':''}" data-account=""><div class="between"><b>${t('全部账户','All accounts')}</b>${icon('wallet')}</div><div class="amount">${fmt(data.accounts.reduce((n,a)=>n+C.convert(data,C.balance(data,a.id),a.currency,data.settings.currency),0))}</div><small>${t('净资产','Net worth')} · ${data.settings.currency}</small></button>${data.accounts.map(a=>`<button class="account-chip ${a.id===selectedAccount?'active':''}" data-account="${esc(a.id)}"><div class="between"><b>${esc(a.name)}</b><i class="color-dot" style="--card-color:${a.color}"></i></div><div class="amount">${fmt(C.balance(data,a.id),a.currency)}</div><small>${data.transactions.filter(t=>t.account===a.id||t.toAccount===a.id).length} ${t('笔交易','transactions')} · ${a.currency}</small></button>`).join('')}<button class="account-chip add" data-action="add-account" aria-label="${t('新增账户','Add account')}">${icon('plus')}</button></div>`;}
function home(){const visible=data.settings.widgets;const blocks={budgets:()=>`<section><div class="panel-title"><h2>${t('我的预算','Your budgets')}</h2><button class="link" data-nav="budgets">${t('查看全部','View all')} ${icon('right')}</button></div>${data.budgets.length?budgetCard(data.budgets[0]):`<div class="panel">${empty(t('给开销一个计划','Give your spending a plan'),t('建立第一个预算，了解还能花多少。','Create a budget to see what’s left.'),'add-budget',t('创建预算','Create budget'))}</div>`}${data.budgets.length>1?'<div style="height:15px"></div>'+budgetCard(data.budgets[1]):''}</section>`,summary:()=>summaryPanel(),chart:()=>`<section class="panel"><div class="panel-title"><h2>${t('支出分类','Spending breakdown')}</h2><button class="link" data-nav="analysis">${t('详细统计','Details')} ${icon('right')}</button></div>${donut('expense')}${lineChart('expense')}</section>`,goals:()=>`<section class="panel"><div class="panel-title"><h2>${t('一点点，靠近目标','A little closer')}</h2>${I('plus','add-goal',t('添加目标','Add goal'))}</div>${data.goals.length?data.goals.slice(0,3).map(goalRow).join(''):empty(t('你的下一个小目标？','What are you saving for?'),t('旅行、新电脑，或者一份安心。','A trip, a new laptop, or peace of mind.'),'add-goal',t('添加目标','Add goal'))}</section>`,upcoming:()=>upcomingPanel(),transactions:()=>`<section class="panel"><div class="panel-title"><h2>${t('最近交易','Recent transactions')}</h2><button class="link" data-nav="transactions">${t('查看全部','View all')} ${icon('right')}</button></div><div class="segmented">${[['','全部','All'],['expense','支出','Outgoing'],['income','收入','Incoming']].map(([v,z,e])=>`<button class="${homeType===v?'active':''}" data-home-type="${v}">${t(z,e)}</button>`).join('')}</div>${txList(C.filtered(data,{...monthPeriod(),account:selectedAccount,type:homeType}).slice(0,8))}</section>`};const left=[],right=[];visible.forEach(key=>{(['budgets','summary','goals'].includes(key)?left:right).push(blocks[key]());});return `${accountStrip()}<div class="row wrap" style="margin-bottom:20px"><span class="pill">${icon('calendar')}${mLabel()}</span>${btn(t('自定义首页','Customize home'),'customize','edit','plain small')}</div><div class="dashboard"><div class="column">${left.join('')}</div><div class="column">${right.join('')}</div></div><p class="footer-note">${t('每一笔小记录，都让生活更清晰。','Small entries. A clearer picture.')}<br>${t('数据保存在此浏览器 · 记得定期导出备份','Stored in this browser · Export a backup regularly')}</p>`;}
function summaryPanel(){const s=C.summary(data,{...monthPeriod(),account:selectedAccount});return `<section class="panel"><div class="panel-title"><h2>${t('本月概览','This month')}</h2><span class="pill">${mLabel()}</span></div><div class="spending-grid"><div class="stat"><small>${icon('arrowDown')} ${t('收入','Income')}</small><div class="amount green">${fmt(s.income)}</div><small>${t('流入账户','Money in')}</small></div><div class="stat"><small>${icon('arrowUp')} ${t('支出','Expenses')}</small><div class="amount red">${fmt(s.expense)}</div><small>${t('日常开销','Money out')}</small></div></div><div class="between" style="margin-top:19px;font-size:13px"><span class="muted">${t('本月结余','Net cash flow')}</span><b class="${s.net>=0?'green':'red'}">${fmt(s.net)}</b></div></section>`;}
function budgetCard(b){const r=C.budgetResult(data,b,budgetDate()),days=Math.max(1,Math.ceil((C.parseDate(r.end)-C.parseDate(C.iso()))/86400000)+1),inPeriod=C.iso()>=r.start&&C.iso()<=r.end;const elapsed=Math.min(100,Math.max(0,(C.parseDate(C.iso())-C.parseDate(r.start))/(C.parseDate(r.end)-C.parseDate(r.start)||1)*100));return `<button class="budget-card" data-budget="${esc(b.id)}" style="--card-color:${b.color}"><div class="budget-top"><div class="between"><h2>${esc(b.name)}</h2>${icon('budget')}</div><p><strong>${fmt(Math.abs(r.left),b.currency)}</strong> ${r.left>=0?t('可用 /','left of'):t('超支 /','overspent of')} ${fmt(b.amount,b.currency)}</p></div><div class="budget-content"><div class="between"><small>${dateLabel(r.start)}</small><small>${dateLabel(r.end)}</small></div><div class="budget-track"><div class="fill" style="width:${Math.min(100,r.percent)}%"></div><b>${Math.round(r.percent)}%</b>${inPeriod?`<i style="left:${elapsed}%"></i>`:''}</div><p class="budget-foot">${inPeriod&&r.left>0?t(`每天还可花 ${fmt(Math.floor(r.left/days),b.currency)}，剩余 ${days} 天`,`You can spend ${fmt(Math.floor(r.left/days),b.currency)} a day for ${days} days`):t('点击查看分类限额与预算历史','View category limits and budget history')}</p></div></button>`;}
function breakdown(type){const rows=C.filtered(data,{...monthPeriod(),account:selectedAccount,type,status:'paid'}),map=new Map();rows.forEach(tx=>map.set(tx.category,(map.get(tx.category)||0)+C.txAmount(data,tx,data.settings.currency)));return [...map].map(([id,n])=>({...cat(id),amount:n})).sort((a,b)=>b.amount-a.amount);}
function donut(type){const rows=breakdown(type),total=rows.reduce((n,c)=>n+c.amount,0);let offset=0;const stops=rows.map(c=>{const start=offset;offset+=total?c.amount/total*100:0;return `${c.color} ${start}% ${offset}%`;}).join(',');return `<div class="chart-wrap"><div class="donut" role="img" aria-label="${t('分类合计','Category total')} ${esc(fmt(total))}" style="${total?'background:conic-gradient('+stops+')':''}"><div class="donut-center"><small>${type==='income'?t('总收入','Total income'):t('总支出','Total spent')}</small><strong>${fmt(total)}</strong><small>${rows.length} ${t('个分类','categories')}</small></div></div><div class="legend">${rows.length?rows.slice(0,6).map(c=>`<button class="legend-row" data-category-filter="${esc(c.id)}"><i class="color-dot" style="--card-color:${c.color}"></i><span class="label">${esc(c.name)}</span><b>${fmt(c.amount)}</b></button>`).join(''):`<p class="no-data">${t('添加交易后，这里会展示支出分布。','Add transactions to see your breakdown.')}</p>`}</div></div>`;}
function lineChart(type){const rows=C.filtered(data,{...monthPeriod(),account:selectedAccount,type,status:'paid'}),days=Number(monthPeriod().end.slice(-2)),sums=Array(days).fill(0);rows.forEach(x=>sums[Number(x.date.slice(-2))-1]+=C.txAmount(data,x,data.settings.currency));let sum=0;const values=sums.map(x=>sum+=x),max=Math.max(100,...values),points=values.map((n,i)=>`${i/(days-1)*480},${125-n/max*100}`).join(' ');return `<svg class="line-chart" viewBox="0 0 480 150" preserveAspectRatio="none" role="img" aria-label="${t('本月累计金额趋势','Cumulative monthly total')}"><defs><linearGradient id="gradient-${type}" x1="0" x2="0" y1="0" y2="1"><stop stop-color="var(--accent)" stop-opacity=".3"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs>${[25,75,125].map(y=>`<path d="M0 ${y}H480" stroke="var(--line)" stroke-dasharray="3 6"/>`).join('')}<polygon points="0,145 ${points} 480,145" fill="url(#gradient-${type})"/><polyline points="${points}" fill="none" stroke="var(--accent)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/></svg><div class="axis"><span>1 ${t('日','')}</span><span>${t('累计趋势','Cumulative trend')}</span><span>${days} ${t('日','')}</span></div>`;}
function txRow(x){const c=cat(x.category)||{icon:'transfer',color:data.settings.accent,name:t('转账','Transfer')};return `<button class="tx-row" data-tx="${esc(x.id)}"><span class="category-icon" style="--card-color:${c.color}">${icon(x.type==='transfer'?'transfer':c.icon)}</span><span class="tx-copy"><b>${esc(x.title)}</b><small>${esc(c.name)} · ${esc(acc(x.account)?.name)} ${x.status==='pending'?' · '+t('待支付','Pending'):''}${x.tags.length?' · #'+esc(x.tags[0]):''}</small></span><span class="tx-money ${x.type==='income'?'green':''}">${x.type==='income'?'+':x.type==='expense'?'−':''}${fmt(x.amount,acc(x.account)?.currency)}${x.type==='transfer'?'<small>→ '+esc(acc(x.toAccount)?.name)+'</small>':''}</span></button>`;}
function txList(rows,selection=false){if(!rows.length)return empty(t('还没有交易','No transactions yet'),t('从记下第一笔开始。','Start with your first entry.'),'add-tx',t('记一笔','Add transaction'));let prev='';return rows.map(x=>{let h='';if(prev!==x.date){prev=x.date;const dayRows=rows.filter(r=>r.date===x.date&&r.status==='paid'&&r.type!=='transfer'),net=dayRows.reduce((n,r)=>n+C.txAmount(data,r,data.settings.currency)*(r.type==='income'?1:-1),0);h=`<div class="date-group"><span>${dateLabel(x.date)}</span><span>${fmt(net)}</span></div>`;}return h+(selection?`<div class="check-batch"><input type="checkbox" data-select-tx="${esc(x.id)}" aria-label="${esc(x.title)}" ${selected.has(x.id)?'checked':''}>${txRow(x)}</div>`:txRow(x));}).join('');}
function transactionPage(){const rows=C.filtered(data,{...filters,query});return `<div class="filter-bar"><input type="search" id="tx-search" placeholder="${t('搜索名称、备注或标签…','Search title, notes or tags…')}" value="${esc(query)}" aria-label="${t('搜索交易','Search transactions')}">${select('filter-account',[['',t('全部账户','All accounts')],...accountOptions()],filters.account||'','id="filter-account"')}${select('filter-type',[['',t('全部类型','All types')],['expense',t('支出','Expense')],['income',t('收入','Income')],['transfer',t('转账','Transfer')]],filters.type||'','id="filter-type"')}${btn(t('筛选','Filters'),'filters','categories','small')}${btn(batch?t('完成','Done'):t('多选','Select'),'batch','check','small')}${btn('CSV','export-csv','download','small')}</div><div class="between wrap" style="margin-bottom:16px"><small id="tx-count">${rows.length} ${t('笔交易','transactions')}</small><div class="row">${btn(t('清除筛选','Clear filters'),'clear-filters','','plain small')}${batch?btn(t('全选结果','Select all'),'select-all','','small')+btn(t('删除所选','Delete selected'),'delete-selected','trash','danger small'):''}</div></div><section class="panel" id="tx-results">${txList(rows,batch)}</section>`;}
function budgetPage(){return `<div class="between wrap" style="margin-bottom:22px"><div class="row">${monthSwitcher()}</div>${btn(t('新增预算','New budget'),'add-budget','plus','primary')}</div><div class="page-grid">${data.budgets.length?data.budgets.map(budgetCard).join(''):`<div class="panel full">${empty(t('预算，让花钱更从容','A plan for your spending'),t('支持每日、每周、每月、每年和自定义周期。','Daily, weekly, monthly, yearly and custom periods.'),'add-budget',t('创建预算','Create budget'))}</div>`}</div>`;}
function goalRow(g){const value=C.goalProgress(data,g),pct=value/g.amount*100;return `<button class="goal-row" style="width:100%;text-align:left;--card-color:${g.color}" data-goal="${esc(g.id)}"><span class="category-icon">${icon(g.icon)}</span><div class="goal-copy"><div class="between"><b>${esc(g.name)}</b><small>${Math.round(pct)}%</small></div><div class="progress"><span style="width:${Math.max(0,Math.min(100,pct))}%"></span></div><div class="between"><small>${fmt(value,g.currency)} / ${fmt(g.amount,g.currency)}</small>${g.date?'<small>'+dateLabel(g.date)+'</small>':''}</div></div></button>`;}
function goals(){return `<div class="between" style="margin-bottom:22px"><p class="muted">${t('为重要的事情，留一点空间。','Make room for what matters.')}</p>${btn(t('新增目标','New goal'),'add-goal','plus','primary')}</div><div class="page-grid">${data.goals.length?data.goals.map(g=>`<section class="panel">${goalRow(g)}<div class="between" style="margin-top:20px"><span class="pill">${g.type==='saving'?t('储蓄目标','Saving goal'):t('消费目标','Spending goal')}</span>${btn(t('查看进度','View progress'),'goal-detail','','small',`data-id="${esc(g.id)}"`)}</div></section>`).join(''):`<div class="panel full">${empty(t('每一个目标，都值得期待','Something to look forward to'),t('关联交易，持续追踪储蓄或消费目标。','Track saving or spending with linked transactions.'),'add-goal',t('创建目标','Create goal'))}</div>`}</div>`;}
function upcomingPanel(){const pending=data.transactions.filter(x=>x.status==='pending').sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3),rs=data.recurring.filter(r=>r.active).sort((a,b)=>a.next.localeCompare(b.next)).slice(0,3);return `<section class="panel"><div class="panel-title"><h2>${t('即将到来','Coming up')}</h2><button class="link" data-nav="recurring">${t('查看全部','View all')} ${icon('right')}</button></div>${pending.map(txRow).join('')}${rs.map(recurringRow).join('')}${!pending.length&&!rs.length?`<p class="no-data">${t('暂时没有待支付账单。','No upcoming bills. All clear.')}</p>`:''}</section>`;}
function recurringRow(r){const c=cat(r.category);return `<div class="tx-row"><span class="category-icon" style="--card-color:${c?.color}">${icon(c?.icon)}</span><button class="tx-copy" style="text-align:left" data-edit-recurring="${esc(r.id)}"><b>${esc(r.title)} ${!r.active?' · '+t('暂停','Paused'):''}</b><small>${dateLabel(r.next)} · ${periods().find(x=>x[0]===r.frequency)?.[1]} ${r.next<C.iso()?' · '+t('已到期','Due'):''}</small></button><span class="tx-money">${fmt(r.amount,acc(r.account)?.currency)}</span>${r.active?I('check','settle-recurring',t('支付本期','Pay occurrence'),`data-id="${esc(r.id)}"`):''}</div>`;}
function recurring(){const monthly=data.recurring.filter(r=>r.active&&r.type==='expense').reduce((n,r)=>n+C.convert(data,r.amount,acc(r.account).currency,data.settings.currency)*({daily:365/12,weekly:52/12,monthly:1,yearly:1/12}[r.frequency]),0);return `<div class="between wrap" style="margin-bottom:22px"><div><small>${t('预计每月订阅支出','Estimated monthly subscriptions')}</small><h1 style="margin-top:7px">${fmt(Math.round(monthly))}</h1></div>${btn(t('新增周期账单','New recurring bill'),'add-recurring','plus','primary')}</div><section class="panel">${data.recurring.length?data.recurring.map(recurringRow).join(''):empty(t('管理你的周期账单','Keep track of recurring bills'),t('支付本期后，会生成交易并推进到下一期。','Pay an occurrence to record it and move to the next date.'),'add-recurring',t('添加账单','Add bill'))}</section><h2 class="section-heading">${t('待支付交易','Pending transactions')}</h2><section class="panel">${txList(data.transactions.filter(x=>x.status==='pending').sort((a,b)=>a.date.localeCompare(b.date)))}</section>`;}
function accounts(){return `<div class="between" style="margin-bottom:22px"><p class="muted">${t('所有账户，一目了然。','Your money, all in one place.')}</p>${btn(t('新增账户','New account'),'add-account','plus','primary')}</div><div class="page-grid">${data.accounts.map(a=>`<section class="panel" style="--card-color:${a.color}"><div class="between"><span class="category-icon">${icon(a.icon)}</span>${I('edit','edit-account',t('编辑账户','Edit account'),`data-id="${esc(a.id)}"`)}</div><h2 style="margin-top:20px">${esc(a.name)}</h2><div class="detail-amount" style="text-align:left;font-size:32px">${fmt(C.balance(data,a.id),a.currency)}</div><small>${a.currency} · ${data.transactions.filter(t=>t.account===a.id||t.toAccount===a.id).length} ${t('笔交易','transactions')}</small><div class="between" style="margin-top:23px">${btn(t('查看交易','View transactions'),'account-transactions','','small',`data-id="${esc(a.id)}"`)}${btn(t('转账','Transfer'),'transfer','transfer','small',`data-id="${esc(a.id)}"`)}</div></section>`).join('')}</div>`;}
function categories(){return `<div class="between" style="margin-bottom:22px"><p class="muted">${t('按自己的方式整理每一笔。','Organize things your way.')}</p>${btn(t('新增分类','New category'),'add-category','plus','primary')}</div><div class="page-grid">${data.categories.map(c=>`<button class="list-card" data-edit-category="${esc(c.id)}"><div class="tx-row"><span class="category-icon" style="--card-color:${c.color}">${icon(c.icon)}</span><div class="tx-copy"><b>${esc(c.name)}</b><small>${c.income?t('默认收入','Income by default'):t('默认支出','Expense by default')} · ${data.transactions.filter(x=>x.category===c.id).length} ${t('笔交易','transactions')}</small></div>${icon('edit')}</div></button>`).join('')}</div><div class="section-heading"><h2>${t('自动分类规则','Automatic title rules')}</h2>${btn(t('添加规则','New rule'),'add-rule','plus','small')}</div><section class="panel">${data.rules.length?data.rules.map(r=>`<div class="setting-row"><div class="copy"><b>${esc(r.title)}</b><p>→ ${esc(cat(r.category)?.name)}</p></div>${I('trash','delete-rule',t('删除规则','Delete rule'),`data-id="${esc(r.id)}"`)}</div>`).join(''):`<p class="muted">${t('交易名称包含关键词时，自动选择分类。','Choose a category automatically when a title includes a keyword.')}</p>`}</section>`;}
function analysis(){const s=C.summary(data,{...monthPeriod(),account:selectedAccount});const cats=breakdown(statsType);return `${accountStrip()}<div class="between wrap" style="margin-bottom:22px"><div class="row">${monthSwitcher()}</div><div class="segmented"><button data-stats="expense" class="${statsType==='expense'?'active':''}">${t('支出','Expenses')}</button><button data-stats="income" class="${statsType==='income'?'active':''}">${t('收入','Income')}</button></div></div><div class="page-grid"><section class="panel"><div class="panel-title"><h2>${statsType==='expense'?t('支出分布','Spending breakdown'):t('收入分布','Income breakdown')}</h2></div>${donut(statsType)}${lineChart(statsType)}</section><section class="panel"><div class="panel-title"><h2>${t('每日记录','Daily activity')}</h2><small>${mLabel()}</small></div>${calendar()}</section><section class="panel"><div class="panel-title"><h2>${t('分类详情','Category details')}</h2><small>${t('点击查看交易','Click to view entries')}</small></div>${cats.map(c=>`<button class="tx-row" data-category-filter="${esc(c.id)}"><span class="category-icon" style="--card-color:${c.color}">${icon(c.icon)}</span><div class="tx-copy"><b>${esc(c.name)}</b><div class="progress" style="--card-color:${c.color};height:6px"><span style="width:${c.amount/Math.max(1,statsType==='expense'?s.expense:s.income)*100}%"></span></div></div><b>${fmt(c.amount)}</b></button>`).join('')||'<p class="muted">'+t('本月暂无记录','No entries this month')+'</p>'}</section>${summaryPanel()}</div>`;}
function calendar(){const days=Number(monthPeriod().end.slice(-2)),offset=(C.parseDate(month+'-01').getDay()+6)%7;const rows=C.filtered(data,{...monthPeriod(),account:selectedAccount,type:statsType,status:'paid'});return `<div class="calendar">${t('一 二 三 四 五 六 日','M T W T F S S').split(' ').map(x=>`<div class="weekday">${x}</div>`).join('')}${'<div></div>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const date=month+'-'+String(i+1).padStart(2,'0'),sum=rows.filter(x=>x.date===date).reduce((s,x)=>s+C.txAmount(data,x,data.settings.currency),0);return `<button class="day ${sum?'has':''}" data-date-filter="${date}" title="${date} ${esc(fmt(sum))}">${i+1}${sum?'<small>'+fmt(sum)+'</small>':''}</button>`;}).join('')}</div>`;}
function debts(){const outstanding=type=>data.debts.filter(d=>d.type===type).reduce((s,d)=>s+C.convert(data,C.debtRemaining(data,d),d.currency,data.settings.currency),0);return `<div class="between wrap" style="margin-bottom:22px"><div class="row wrap"><span class="pill">${t('待收回','To collect')} ${fmt(outstanding('lent'))}</span><span class="pill">${t('待偿还','To repay')} ${fmt(outstanding('borrowed'))}</span></div>${btn(t('新增借贷','New loan'),'add-debt','plus','primary')}</div><div class="page-grid">${data.debts.length?data.debts.map(d=>{const left=C.debtRemaining(data,d);return `<section class="panel"><div class="between"><span class="pill">${d.type==='lent'?t('借出','Lent'):t('借入','Borrowed')}</span>${I('info','debt-detail',t('借贷详情','Loan details'),`data-id="${esc(d.id)}"`)}</div><h2 style="margin-top:18px">${esc(d.name)}</h2><div class="detail-amount" style="text-align:left;font-size:30px">${fmt(left,d.currency)}</div><small>${t('剩余 / 本金','Remaining / principal')} ${fmt(d.amount,d.currency)}</small><div class="progress"><span style="width:${(d.amount-left)/Math.max(1,d.amount)*100}%"></span></div><div class="between"><small>${d.due?dateLabel(d.due):t('无到期日','No due date')}</small>${left?btn(d.type==='lent'?t('收回款项','Collect payment'):t('偿还款项','Repay'),'repay','','small',`data-id="${esc(d.id)}"`):'<span class="pill">'+t('已结清','Settled')+'</span>'}</div></section>`;}).join(''):`<div class="panel full">${empty(t('借与还，记得清楚','Keep lending and borrowing clear'),t('本金和每次还款都关联真实交易。','Principal and repayments link to recorded transactions.'),'add-debt',t('新增借贷','New loan'))}</div>`}</div>`;}
function splitter(){return `<div class="panel" style="max-width:760px"><div class="panel-title"><h2>${t('轻松分摊一笔账单','Split a bill')}</h2>${icon('split')}</div><form id="split-form"><div class="form-grid">${field(t('账单总额','Total bill'),input('total','','number','required min="0.01" step="0.01"'))}${field(t('货币','Currency'),select('currency',currencies(),data.settings.currency))}${field(t('参与人（每行一人）','Participants (one per line)'),'<textarea name="people" required placeholder="'+t('我\n朋友 A\n朋友 B','Me\nFriend A\nFriend B')+'"></textarea>',true)}${field(t('付款人','Paid by'),input('payer','', 'text','required placeholder="'+t('输入上方的一个名字','One of the names above')+'"'),true)}</div><div class="info">${t('平均分摊到分，多出的几分按名单顺序分配。此工具仅计算，不自动创建交易。','Split equally to the cent; remaining cents go in list order. This calculator does not create transactions.')}</div><button class="btn primary" type="submit">${t('计算分摊','Calculate split')}</button><p id="split-error" class="error"></p></form><div id="split-result"></div></div>`;}
function settings(){return `<div class="settings-layout"><section class="panel"><h2>${t('个性化','Make it yours')}</h2><form id="settings-form"><label class="setting-row"><span class="category-icon">${icon('home')}</span><span class="copy"><b>${t('你的名字','Your name')}</b><p>${t('显示在首页问候语中','Shown in your home greeting')}</p></span>${input('name',data.settings.name,'text','maxlength="80"')}</label><label class="setting-row"><span class="category-icon">${icon('sun')}</span><span class="copy"><b>${t('外观','Appearance')}</b></span>${select('theme',[['light',t('浅色','Light')],['dark',t('深色','Dark')],['system',t('跟随系统','System')]],data.settings.theme)}</label><label class="setting-row"><span class="category-icon">${icon('categories')}</span><span class="copy"><b>${t('主题色','Accent color')}</b></span>${input('accent',data.settings.accent,'color')}</label><label class="setting-row"><span class="category-icon">${icon('book')}</span><span class="copy"><b>${t('语言','Language')}</b></span>${select('language',[['zh','简体中文'],['en','English']],data.settings.language)}</label><label class="setting-row"><span class="category-icon">${icon('cash')}</span><span class="copy"><b>${t('统计货币','Display currency')}</b><p>${t('不改变交易的原始货币','Original transaction currencies are preserved')}</p></span>${select('currency',currencies(),data.settings.currency)}</label><div class="modal-footer"><button type="submit" class="btn primary">${t('保存设置','Save preferences')}</button></div></form><button class="setting-row" data-action="customize"><span class="category-icon">${icon('edit')}</span><span class="copy"><b>${t('自定义首页','Customize home')}</b><p>${t('显示、隐藏与排序首页模块','Show, hide and reorder home sections')}</p></span>${icon('right')}</button><button class="setting-row" data-action="rates"><span class="category-icon">${icon('transfer')}</span><span class="copy"><b>${t('汇率','Exchange rates')}</b><p>${t('手动维护；内置数值为示例，非实时汇率','Manual rates; bundled rates are examples, not live')}</p></span>${icon('right')}</button></section><section class="panel"><h2>${t('数据与备份','Data & backups')}</h2><div class="setting-row"><span class="category-icon">${icon('shield')}</span><div class="copy"><b>${t('数据保存在此浏览器','Your data stays in this browser')}</b><p>${t('清除浏览器数据会删除本地记录。建议定期导出 JSON 完整备份。','Clearing browser data removes local records. Export a full JSON backup regularly.')}</p></div></div><div class="row wrap" style="margin-top:18px">${btn(t('完整备份 JSON','Full JSON backup'),'export-json','download')}${btn(t('恢复备份','Restore backup'),'import-json','upload')}${btn(t('导出 CSV','Export CSV'),'export-csv','download')}${btn(t('导入 CSV','Import CSV'),'import-csv','upload')}</div><p class="info">${t('JSON 可完整还原本 HTML 版的所有记录与设置（不兼容原版 Cashew 的 SQLite 备份）。CSV 用于交易交换：请先导出一个 CSV 查看字段格式，导入前先建立同名账户和分类。','JSON restores this HTML edition’s records and preferences; upstream Cashew SQLite backups are not compatible. CSV exchanges transactions. Export a sample and create matching accounts/categories before importing.')}</p>${btn(t('下载 CSV 模板','Download CSV template'),'csv-template','download','small')}</section><section class="panel"><h2>${t('云端连接','Cloud connection')}</h2><p class="info">${t('默认完全本地运行。可连接你部署的 Cloudflare Worker。使用完整快照上传/下载并检测版本冲突；不会在后台自动合并。访问令牌只保存在当前页面内存中。','Local by default. Connect your own Cloudflare Worker for version-checked snapshot upload/download. No automatic merging. The access token stays in page memory only.')}</p><form id="cloud-form">${field('Worker API URL',input('url',data.settings.apiUrl||window.CASHEW_CONFIG?.apiBaseUrl||'','url','placeholder="https://your-worker.workers.dev"'))}${field(t('访问令牌（本次会话）','Access token (this session)'),input('token','','password','autocomplete="off"'))}<p id="cloud-status" class="muted" style="font-size:12px">${t('未连接','Not connected')}</p><div class="row wrap" style="margin-top:18px"><button type="submit" class="btn">${icon('link')}${t('连接并检查','Connect & check')}</button>${btn(t('上传本地快照','Upload local snapshot'),'cloud-push','upload')}${btn(t('下载云端快照','Download cloud snapshot'),'cloud-pull','download')}</div></form></section><section class="panel"><h2>${t('关于这个版本','About this edition')}</h2><div class="setting-row"><img src="assets/icon.png" width="48" height="48" alt=""><div class="copy"><b>Cashew HTML · v1.0.0</b><p>${t('依据 James Kokoska / Cashew 重实现 · 非官方 HTML 移植','An unofficial HTML reimplementation of James Kokoska / Cashew')}<br>GPL-3.0 · <a href="https://github.com/jameskokoska/Cashew" target="_blank" rel="noopener">${t('原始项目','Original project')}</a></p></div></div><p class="info">${t('本地版已提供记账、预算、账户、统计、周期账单、借贷、目标与备份。原版 Google 登录/Drive 同步、共享预算、原生生物识别、后台推送及邮件/Google Sheets 自动导入未实现。界面遵循原版 Material You 布局，尚未通过逐屏像素级一致性验证。','Includes local transactions, budgets, accounts, analytics, recurring bills, loans, goals and backups. Google login/Drive, shared budgets, native biometrics, background push and email/Google Sheets automation are not implemented. Material You layout follows the original; pixel parity has not been verified.')}</p><div class="row wrap">${btn(t('加载示例数据','Load demo data'),'load-demo','transactions')}${btn(t('开始空白账本','Start empty ledger'),'reset','','danger')}</div></section></div>`;}
function showTx(id){const x=data.transactions.find(x=>x.id===id);if(!x)return;const currency=acc(x.account)?.currency,c=cat(x.category);modal(t('交易详情','Transaction details'),`<div class="detail-amount ${x.type==='income'?'green':''}">${x.type==='income'?'+':x.type==='expense'?'−':''}${fmt(x.amount,currency)}</div><h3 class="detail-title">${esc(x.title)}</h3><div class="detail-list">${[[t('日期','Date'),x.date],[t('账户','Account'),acc(x.account)?.name],[t('分类','Category'),x.type==='transfer'?t('转账','Transfer'):c?.name],[t('状态','Status'),x.status==='paid'?t('已支付','Paid'):t('待支付','Pending')],...(x.type==='transfer'?[[t('转入账户','To account'),acc(x.toAccount)?.name+' · '+fmt(x.toAmount,acc(x.toAccount)?.currency)]]:[]),...(x.goalId?[[t('关联目标','Linked goal'),data.goals.find(g=>g.id===x.goalId)?.name]]:[]),...(x.tags.length?[[t('标签','Tags'),x.tags.map(t=>'#'+t).join(' ')]]:[]),...(x.notes?[[t('备注','Notes'),x.notes]]:[])].map(([l,v])=>`<div class="between"><span class="muted">${l}</span><span class="text-wrap">${esc(v)}</span></div>`).join('')}</div>${x.attachments.map(a=>`<img class="attachment" src="${a.data}" alt="${esc(a.name)}">`).join('')}<div class="modal-footer">${btn(t('删除','Delete'),'delete-tx','trash','danger',`data-id="${esc(id)}"`)}${!x.debtId?btn(t('复制','Duplicate'),'duplicate-tx','','',`data-id="${esc(id)}"`):''}${x.status==='pending'?btn(t('标记支付','Mark paid'),'pay-tx','check','primary',`data-id="${esc(id)}"`):''}${!x.debtId?btn(t('编辑','Edit'),'edit-tx','edit','primary',`data-id="${esc(id)}"`):''}</div>`);}
function txForm(id='',preset={}){const existing=data.transactions.find(x=>x.id===id),x=existing||{id:'',title:'',amount:0,type:'expense',date:C.iso(),account:selectedAccount||data.accounts[0].id,category:data.categories[0].id,status:'paid',notes:'',tags:[],budgetIds:[],goalId:'',attachments:[],...preset};attachments=structuredClone(x.attachments||[]);modal(existing?t('编辑交易','Edit transaction'):t('添加交易','Add transaction'),`<form id="tx-form" data-id="${esc(x.id)}"><div class="segmented" id="tx-type-tabs">${[['expense','支出','Expense'],['income','收入','Income'],['transfer','转账','Transfer']].map(([v,z,e])=>`<button type="button" data-form-type="${v}" class="${x.type===v?'active':''}">${t(z,e)}</button>`).join('')}</div><input type="hidden" name="type" value="${x.type}">${input('amount',x.amount?num(x.amount):'','number','required min="0.01" max="100000000000" step="0.01" placeholder="0.00" class="amount-input" aria-label="'+t('金额','Amount')+'"')}<p class="amount-caption" id="amount-currency">${acc(x.account)?.currency}</p><div class="spacer"></div><div class="form-grid">${field(t('名称','Title'),input('title',x.title,'text','required maxlength="120" autocomplete="off" list="recent-titles"'),true)}<datalist id="recent-titles">${[...new Set(data.transactions.map(x=>x.title))].slice(-150).map(s=>`<option value="${esc(s)}">`).join('')}</datalist>${field(t('账户','Account'),select('account',accountOptions(),x.account))}${field(t('日期','Date'),input('date',x.date,'date','required'))}<div class="field" id="tx-category-field"><span>${t('分类','Category')}</span>${select('category',categoryOptions(),x.category)}</div><div class="field" id="tx-goal-field"><span>${t('目标','Goal')}</span>${select('goalId',[['',t('不关联','None')],...data.goals.map(g=>[g.id,g.name])],x.goalId||'')}</div><div class="field" id="tx-to-field" ${x.type!=='transfer'?'hidden':''}><span>${t('转入账户','To account')}</span>${select('toAccount',accountOptions(),x.toAccount||data.accounts.find(a=>a.id!==x.account)?.id)}</div><div class="field" id="tx-to-amount-field" ${x.type!=='transfer'?'hidden':''}><span>${t('转入金额（转入账户货币）','Received amount (destination currency)')}</span>${input('toAmount',x.toAmount?num(x.toAmount):'','number','min="0.01" step="0.01" placeholder="'+t('留空按设置汇率换算','Blank: use configured rate')+'"')}</div>${field(t('状态','Status'),select('status',[['paid',t('已支付','Paid')],['pending',t('待支付 / 即将到来','Pending / upcoming')]],x.status))}${field(t('标签（逗号分隔）','Tags (comma-separated)'),input('tags',x.tags.join(', '),'text','maxlength="1000"'))}${field(t('备注','Notes'),`<textarea name="notes" maxlength="10000">${esc(x.notes)}</textarea>`,true)}<div class="field full" id="tx-budgets-field"><span>${t('加入预算（手动选择模式）','Add to selected budgets')}</span>${data.budgets.length?checkOptions('budgetIds',data.budgets.map(b=>[b.id,b.name]),x.budgetIds):'<small>'+t('尚无预算','No budgets yet')+'</small>'}</div><div class="field full"><span>${t('收据附件（PNG/JPG/WebP，每张 ≤ 2 MB）','Receipt (PNG/JPG/WebP, up to 2 MB each)')}</span><input type="file" id="receipt-file" accept="image/png,image/jpeg,image/webp"><div id="receipt-list">${attachmentList()}</div></div></div>${formFooter()}</form>`);updateTxType(x.type);}
function attachmentList(){return attachments.map((a,i)=>`<div class="between"><small>${esc(a.name)}</small>${btn(t('移除','Remove'),'remove-attachment','close','small',`data-index="${i}"`)}</div>`).join('');}
function updateTxType(type){const form=$('#tx-form');if(!form)return;form.elements.type.value=type;form.querySelectorAll('[data-form-type]').forEach(b=>b.classList.toggle('active',b.dataset.formType===type));['tx-category-field','tx-goal-field','tx-budgets-field'].forEach(id=>{const el=$('#'+id);el.style.display=type==='transfer'?'none':'';});['tx-to-field','tx-to-amount-field'].forEach(id=>{$('#'+id).style.display=type==='transfer'?'':'none';$('#'+id).hidden=type!=='transfer';});}
function budgetForm(id){const b=data.budgets.find(x=>x.id===id)||{id:'',name:'',amount:0,currency:data.settings.currency,period:'monthly',start:C.iso(),end:C.period().end,categories:[],accounts:[],mode:'all',color:'#86a58c',limits:{}};modal(b.id?t('编辑预算','Edit budget'):t('新增预算','New budget'),`<form id="budget-form" data-id="${esc(b.id)}"><div class="form-grid">${field(t('预算名称','Budget name'),input('name',b.name,'text','required maxlength="120"'),true)}${field(t('预算金额','Amount'),input('amount',b.amount?num(b.amount):'','number','required min="0.01" step="0.01"'))}${field(t('货币','Currency'),select('currency',currencies(),b.currency))}${field(t('周期','Period'),select('period',periods(),b.period))}${field(t('颜色','Color'),input('color',b.color,'color'))}${field(t('自定义开始日期','Custom start date'),input('start',b.start,'date','required'))}${field(t('自定义结束日期','Custom end date'),input('end',b.end,'date','required'))}${field(t('纳入交易','Transactions included'),select('mode',[['all',t('自动统计匹配交易','All matching transactions')],['selected',t('手动选择交易','Manually added transactions')]],b.mode),true)}<div class="field full"><span>${t('分类筛选（不选 = 全部）','Categories (none selected = all)')}</span>${checkOptions('categories',categoryOptions(),b.categories)}</div><div class="field full"><span>${t('账户筛选（不选 = 全部）','Accounts (none selected = all)')}</span>${checkOptions('accounts',accountOptions(),b.accounts)}</div><div class="field full"><span>${t('各分类限额（可留空）','Category limits (optional)')}</span><div class="form-grid">${data.categories.filter(c=>!c.income).map(c=>field(esc(c.name),input('limit-'+c.id,b.limits[c.id]?num(b.limits[c.id]):'','number','min="0" step="0.01"'))).join('')}</div></div></div><small>${t('固定周期按日历计算；自定义起止日期仅在自定义周期生效。','Fixed periods follow the calendar. Start/end dates apply to custom periods.')}</small>${formFooter()}</form>`);}
function budgetDetail(id){const b=data.budgets.find(x=>x.id===id);if(!b)return;const r=C.budgetResult(data,b,budgetDate());modal(esc(b.name),`${budgetCard(b)}<div class="section-heading"><h3>${t('分类限额','Category limits')}</h3><small>${mLabel()}</small></div>${Object.entries(b.limits).length?Object.entries(b.limits).map(([id,limit])=>{const c=cat(id),spent=r.rows.filter(x=>x.category===id).reduce((s,x)=>s+C.txAmount(data,x,b.currency),0);return `<div class="goal-row" style="--card-color:${c.color}"><span class="category-icon">${icon(c.icon)}</span><div class="goal-copy"><div class="between"><b>${esc(c.name)}</b><small class="${spent>limit?'red':''}">${fmt(spent,b.currency)} / ${fmt(limit,b.currency)}</small></div><div class="progress"><span style="width:${Math.min(100,spent/Math.max(1,limit)*100)}%"></span></div></div></div>`;}).join(''):'<p class="no-data">'+t('没有设置分类限额','No category limits set')+'</p>'}<div class="section-heading"><h3>${t('历史周期','Budget history')}</h3></div>${(b.period==='custom'?[0]:[0,1,2,3,4,5]).map(i=>{const d=C.shift(budgetDate(),b.period,-i),r=C.budgetResult(data,b,d);return `<div class="history-row"><div><b>${r.start} — ${r.end}</b><p><small>${fmt(Math.abs(r.left),b.currency)} ${r.left>=0?t('剩余','remaining'):t('超支','overspent')}</small></p></div><div class="tiny-ring" style="--p:${Math.min(100,r.percent)}%"><b>${Math.round(r.percent)}%</b></div></div>`;}).join('')}<div class="section-heading"><h3>${t('本期交易','Transactions in period')}</h3></div>${txList(r.rows)}<div class="modal-footer">${btn(t('删除预算','Delete budget'),'delete-budget','trash','danger',`data-id="${esc(id)}"`)}${btn(t('编辑预算','Edit budget'),'edit-budget','edit','primary',`data-id="${esc(id)}"`)}</div>`);}
const iconsForSelect=['wallet','bank','cash','restaurant','basket','bag','car','home','game','heart','work','plane','book','coffee','gift','phone','pet','target','calendar','dots'];
function accountForm(id){const a=data.accounts.find(a=>a.id===id)||{id:'',name:'',currency:data.settings.currency,opening:0,color:'#85aa91',icon:'wallet'};const hasTransactions=!!id&&(data.transactions.some(t=>t.account===id||t.toAccount===id)||data.recurring.some(r=>r.account===id)||data.debts.some(r=>r.account===id));modal(a.id?t('编辑账户','Edit account'):t('新增账户','New account'),`<form id="account-form" data-id="${esc(a.id)}"><div class="form-grid">${field(t('账户名称','Account name'),input('name',a.name,'text','required maxlength="120"'),true)}${field(t('货币','Currency'),select('currency',currencies(),a.currency,hasTransactions?'disabled':''))}${field(t('期初余额','Opening balance'),input('opening',num(a.opening),'number','required step="0.01"'))}${field(t('颜色','Color'),input('color',a.color,'color'))}${field(t('图标','Icon'),select('icon',iconsForSelect.map(i=>[i,i]),a.icon))}</div><p class="info">${t('当前余额 = 期初余额 + 已支付收入 − 已支付支出 ± 转账。有关联记录后不能直接更改账户货币。','Balance = opening balance + paid income − paid expenses ± transfers. Currency is locked once records reference this account.')}</p>${a.id?btn(t('删除账户','Delete account'),'delete-account','trash','danger small',`data-id="${esc(a.id)}"`):''}${formFooter()}</form>`);}
function categoryForm(id){const c=cat(id)||{id:'',name:'',income:false,color:'#83ad87',icon:'bag'};modal(c.id?t('编辑分类','Edit category'):t('新增分类','New category'),`<form id="category-form" data-id="${esc(c.id)}">${field(t('分类名称','Category name'),input('name',c.name,'text','required maxlength="120"'))}<div class="form-grid">${field(t('颜色','Color'),input('color',c.color,'color'))}${field(t('默认类型','Default type'),select('income',[['no',t('支出','Expense')],['yes',t('收入','Income')]],c.income?'yes':'no'))}</div><div class="field"><span>${t('图标','Icon')}</span><input type="hidden" name="icon" value="${esc(c.icon)}"><div class="icon-picker">${iconsForSelect.map(i=>`<button type="button" data-pick-icon="${i}" title="${i}" aria-label="${i}" class="${i===c.icon?'selected':''}">${icon(i)}</button>`).join('')}</div></div>${c.id?btn(t('删除分类','Delete category'),'delete-category','trash','danger small',`data-id="${esc(c.id)}"`):''}${formFooter()}</form>`);}
function goalForm(id){const g=data.goals.find(g=>g.id===id)||{id:'',name:'',amount:0,initial:0,currency:data.settings.currency,color:'#85aebb',icon:'target',type:'saving',date:''};modal(g.id?t('编辑目标','Edit goal'):t('新增目标','New goal'),`<form id="goal-form" data-id="${esc(g.id)}"><div class="form-grid">${field(t('目标名称','Goal name'),input('name',g.name,'text','required maxlength="120"'),true)}${field(t('目标金额','Target amount'),input('amount',g.amount?num(g.amount):'','number','required min="0.01" step="0.01"'))}${field(t('已完成初始金额','Initial progress'),input('initial',num(g.initial),'number','required step="0.01"'))}${field(t('货币','Currency'),select('currency',currencies(),g.currency))}${field(t('目标类型','Goal type'),select('type',[['saving',t('储蓄：收入增加进度','Saving: income adds progress')],['spending',t('消费：支出增加进度','Spending: expenses add progress')]],g.type))}${field(t('目标日期','Target date'),input('date',g.date,'date'))}${field(t('颜色','Color'),input('color',g.color,'color'))}${field(t('图标','Icon'),select('icon',iconsForSelect.map(i=>[i,i]),g.icon))}</div><p class="info">${t('目标进度按初始金额与关联交易计算。储蓄目标的关联支出会扣减进度；消费目标相反。','Progress comes from the initial value and linked transactions. Linked expenses reduce savings progress; spending goals work in reverse.')}</p>${formFooter()}</form>`);}
function goalDetail(id){const g=data.goals.find(g=>g.id===id);if(!g)return;modal(esc(g.name),`${goalRow(g)}<p class="info">${t('初始进度','Initial progress')} ${fmt(g.initial,g.currency)} · ${t('剩余','Remaining')} ${fmt(Math.max(0,g.amount-C.goalProgress(data,g)),g.currency)}</p>${btn(t('添加关联交易','Add linked transaction'),'goal-transaction','plus','primary',`data-id="${esc(id)}"`)}<div class="section-heading"><h3>${t('关联交易','Linked transactions')}</h3></div>${txList(C.filtered(data).filter(t=>t.goalId===id))}<div class="modal-footer">${btn(t('删除目标','Delete goal'),'delete-goal','trash','danger',`data-id="${esc(id)}"`)}${btn(t('编辑','Edit'),'edit-goal','edit','',`data-id="${esc(id)}"`)}</div>`);}
function recurringForm(id){const r=data.recurring.find(r=>r.id===id)||{id:'',title:'',amount:0,account:selectedAccount||data.accounts[0].id,category:data.categories[0].id,type:'expense',next:C.iso(),frequency:'monthly',active:true,notes:'',tags:[]};modal(r.id?t('编辑周期账单','Edit recurring bill'):t('新增周期账单','New recurring bill'),`<form id="recurring-form" data-id="${esc(r.id)}"><div class="form-grid">${field(t('名称','Title'),input('title',r.title,'text','required maxlength="120"'),true)}${field(t('金额','Amount'),input('amount',r.amount?num(r.amount):'','number','required min="0.01" step="0.01"'))}${field(t('类型','Type'),select('type',[['expense',t('支出','Expense')],['income',t('收入','Income')]],r.type))}${field(t('账户','Account'),select('account',accountOptions(),r.account))}${field(t('分类','Category'),select('category',categoryOptions(),r.category))}${field(t('下次日期','Next due date'),input('next',r.next,'date','required'))}${field(t('周期','Frequency'),select('frequency',periods().filter(x=>x[0]!=='custom'),r.frequency))}${field(t('状态','Status'),select('active',[['yes',t('启用','Active')],['no',t('暂停','Paused')]],r.active?'yes':'no'))}${field(t('备注','Notes'),`<textarea name="notes" maxlength="10000">${esc(r.notes)}</textarea>`,true)}</div>${r.id?btn(t('删除周期规则','Delete recurring rule'),'delete-recurring','trash','danger small',`data-id="${esc(r.id)}"`):''}${formFooter()}</form>`);}
function debtForm(){modal(t('新增借贷','New loan'),`<form id="debt-form"><div class="form-grid">${field(t('对方姓名 / 名称','Person / name'),input('name','','text','required maxlength="120"'),true)}${field(t('类型','Type'),select('type',[['lent',t('借出（对方欠我）','Lent (owed to me)')],['borrowed',t('借入（我欠对方）','Borrowed (I owe)')]],'lent'))}${field(t('本金','Principal'),input('amount','','number','required min="0.01" step="0.01"'))}${field(t('账户','Account'),select('account',accountOptions(),selectedAccount||data.accounts[0].id))}${field(t('分类','Category'),select('category',categoryOptions(),'other'))}${field(t('借贷日期','Date'),input('date',C.iso(),'date','required'))}${field(t('到期日期（可选）','Due date (optional)'),input('due','','date'))}${field(t('备注','Notes'),'<textarea name="notes" maxlength="10000"></textarea>',true)}</div><p class="info">${t('保存时会新增本金交易：借出为支出，借入为收入。每次还款也会生成相应交易。','Saving records the principal: lending as expense, borrowing as income. Repayments also create transactions.')}</p>${formFooter()}</form>`);}
function repayForm(id){const d=data.debts.find(d=>d.id===id),left=C.debtRemaining(data,d);modal(d.type==='lent'?t('收回款项','Collect payment'):t('偿还款项','Repay'),`<form id="repay-form" data-id="${esc(id)}"><p class="info">${esc(d.name)} · ${t('剩余','Remaining')} ${fmt(left,d.currency)}</p>${field(t('本次金额','Payment amount'),input('amount',num(left),'number',`required min="0.01" max="${num(left)}" step="0.01"`))}${field(t('日期','Date'),input('date',C.iso(),'date','required'))}${formFooter()}</form>`);}
function filterForm(){modal(t('筛选交易','Filter transactions'),`<form id="filters-form"><div class="form-grid">${field(t('开始日期','From'),input('start',filters.start||'','date'))}${field(t('结束日期','To'),input('end',filters.end||'','date'))}${field(t('分类','Category'),select('category',[['',t('全部分类','All categories')],...categoryOptions()],filters.category||''))}${field(t('状态','Status'),select('status',[['',t('全部','All')],['paid',t('已支付','Paid')],['pending',t('待支付','Pending')]],filters.status||''))}${field(t('最低金额（统计货币）','Min amount (display currency)'),input('min',filters.min?num(filters.min):'','number','min="0" step="0.01"'))}${field(t('最高金额（统计货币）','Max amount (display currency)'),input('max',filters.max?num(filters.max):'','number','min="0" step="0.01"'))}</div>${formFooter(t('应用筛选','Apply filters'))}</form>`);}
function confirmAction(title,desc,fn){modal(title,`<p class="info">${desc}</p><div class="modal-footer">${btn(t('取消','Cancel'),'close','','plain')}<button id="confirm-action" class="btn danger">${t('确认','Confirm')}</button></div>`);$('#confirm-action').onclick=()=>{close();fn();};}
function download(text,filename,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function backup(){download(JSON.stringify(data,null,2),`cashew-backup-${C.iso()}.json`);}
function chooseImport(kind){const f=$('#import-file');f.accept=kind==='json'?'.json':'.csv';f.dataset.kind=kind;f.value='';f.click();}
function customize(){const all=['budgets','summary','chart','goals','upcoming','transactions'],names={budgets:t('预算','Budgets'),summary:t('收支概览','Summary'),chart:t('支出图表','Charts'),goals:t('目标','Goals'),upcoming:t('即将到来','Upcoming'),transactions:t('交易','Transactions')},order=[...data.settings.widgets,...all.filter(x=>!data.settings.widgets.includes(x))];modal(t('自定义首页','Customize home'),`<form id="widgets-form"><div id="widget-order">${order.map(x=>`<div class="setting-row" data-widget="${x}"><label class="copy row"><input type="checkbox" name="widget" value="${x}" ${data.settings.widgets.includes(x)?'checked':''}>${names[x]}</label>${I('up','widget-up',t('上移','Move up'))}${I('down','widget-down',t('下移','Move down'))}</div>`).join('')}</div><p class="info">${t('在桌面端，预算/概览/目标位于左列，其余模块位于右列。排序在所属列内生效。','On desktop, budgets/summary/goals are in the left column and other sections on the right. Reordering applies within each column.')}</p>${formFooter()}</form>`);}
function rates(){modal(t('手动汇率','Manual exchange rates'),`<form id="rates-form"><p class="info">${t('以下为每 1 单位货币对应的人民币金额。默认值仅供示例，请输入你自己的汇率。修改汇率会重新计算跨币种统计。','Enter the CNY value of 1 unit of each currency. Defaults are illustrative. Changing rates recalculates cross-currency summaries.')}</p><div class="form-grid">${Object.entries(data.settings.rates).map(([c,v])=>field(c,input(c,v,'number','required min="0.00000001" step="any"'))).join('')}</div>${formFooter()}</form>`);}
function more(){modal(t('更多','More'),Object.keys(labels).map(p=>`<button class="setting-row" data-modal-nav="${p}"><span class="category-icon">${icon(navIcons[p])}</span><b class="copy">${name(p)}</b>${icon('right')}</button>`).join(''));}
function welcome(){modal(t('欢迎来到 Cashew','Welcome to Cashew'),`<div class="welcome"><img src="assets/icon.png" alt="Cashew"><h1>${t('理清财务，\n自在生活。','Your money.\nMade simple.').replaceAll('\n','<br>')}</h1><p>${t('记录每一笔，规划每个月。<br>从一个属于你的账本开始。','Track your spending. Plan your month.<br>A little more clarity, every day.')}</p>${btn(t('创建我的账本','Start my ledger'),'start-blank','plus','primary')}${btn(t('先看看示例','Explore a demo'),'start-demo','chart')}<small>${t('无需注册 · 本地保存 · 支持离线<br>这是非官方 HTML 版，与原版云服务独立。','No account needed · Stored locally · Offline ready<br>Unofficial HTML edition, independent of upstream cloud services.')}</small></div>`);}
let cloudAdapter=null;
async function cloudConnect(form){const f=new FormData(form),url=f.get('url').trim(),token=f.get('token').trim();if(!url||!token)throw Error(t('请输入 API 地址与访问令牌','Enter API URL and access token'));const adapter=new C.WorkerAdapter(url,token),r=await adapter.pull();cloudAdapter=adapter;syncVersion=r.version;persist(d=>{d.settings.apiUrl=url;});$('#cloud-status').textContent=t('已连接，云端版本 ','Connected, cloud version ')+r.version;notify(t('连接成功','Connected'));}
async function cloudPush(){if(!cloudAdapter||syncVersion===null)throw Error(t('请先连接并检查','Connect and check first'));confirmAction(t('上传当前账本？','Upload this ledger?'),t('将用当前本地完整快照替换云端账本。云端版本变化时上传会被拒绝。','Replace the cloud ledger with this local snapshot. A changed cloud version will reject the upload.'),async()=>{try{const r=await cloudAdapter.push(data,syncVersion);syncVersion=r.version;notify(t('已上传，版本 ','Uploaded, version ')+r.version);}catch(e){showError(e);}});}
async function cloudPull(){if(!cloudAdapter)throw Error(t('请先连接','Connect first'));const r=await cloudAdapter.pull();if(!r.data){notify(t('云端尚无账本','Cloud ledger is empty'));return;}confirmAction(t('恢复云端账本？','Restore cloud ledger?'),t('将替换本地所有数据。先导出本地备份，再确认。','This replaces all local data. Export a local backup before confirming.'),()=>{if(persist(d=>Object.assign(d,r.data),t('云端快照已恢复','Cloud snapshot restored')))syncVersion=r.version;});}
function deleteEntity(kind,id){const title=t('确认删除？','Delete this item?');if(kind==='transaction'){const x=data.transactions.find(x=>x.id===id);if(x?.debtId)throw Error(t('借贷交易请在借贷详情中删除整笔借贷，避免余额失配。','Delete the loan from loan details to remove linked entries safely.'));}if(kind==='account'&&(data.accounts.length===1||data.transactions.some(t=>t.account===id||t.toAccount===id)||data.recurring.some(r=>r.account===id)||data.debts.some(d=>d.account===id)))throw Error(t('账户有关联记录，或是最后一个账户，不能删除。','Referenced accounts and the final account cannot be deleted.'));if(kind==='category'&&(data.categories.length===1||data.transactions.some(t=>t.category===id)||data.recurring.some(r=>r.category===id)))throw Error(t('分类有关联记录，或是最后一个分类，不能删除。','Referenced categories and the final category cannot be deleted.'));confirmAction(title,t('删除将保存在本地。此操作不能撤销，建议先备份。','Deletion is saved locally and cannot be undone. Consider exporting a backup.'),()=>persist(d=>{const key={transaction:'transactions',budget:'budgets',goal:'goals',recurring:'recurring',account:'accounts',category:'categories',rule:'rules',debt:'debts'}[kind];d[key]=d[key].filter(x=>x.id!==id);if(kind==='budget')d.transactions.forEach(t=>t.budgetIds=t.budgetIds.filter(x=>x!==id));if(kind==='goal')d.transactions.forEach(t=>{if(t.goalId===id)t.goalId='';});if(kind==='account'){d.budgets.forEach(b=>b.accounts=b.accounts.filter(x=>x!==id));if(selectedAccount===id)selectedAccount='';}if(kind==='category'){d.rules=d.rules.filter(r=>r.category!==id);d.budgets.forEach(b=>{b.categories=b.categories.filter(c=>c!==id);delete b.limits[id];});}if(kind==='debt')d.transactions=d.transactions.filter(t=>t.debtId!==id);},t('已删除','Deleted')));}
async function action(a,b){const id=b?.dataset.id;switch(a){case'close':close();break;case'add-tx':txForm();break;case'edit-tx':txForm(id);break;case'duplicate-tx':{const x=structuredClone(data.transactions.find(x=>x.id===id));delete x.id;delete x.recurringId;delete x.occurrence;txForm('',{...x,date:C.iso()});break;}case'delete-tx':deleteEntity('transaction',id);break;case'pay-tx':if(persist(d=>d.transactions.find(x=>x.id===id).status='paid',t('已标记支付','Marked as paid')))close();break;case'add-budget':budgetForm();break;case'edit-budget':budgetForm(id);break;case'delete-budget':deleteEntity('budget',id);break;case'add-account':accountForm();break;case'edit-account':accountForm(id);break;case'delete-account':deleteEntity('account',id);break;case'add-category':categoryForm();break;case'delete-category':deleteEntity('category',id);break;case'add-goal':goalForm();break;case'edit-goal':goalForm(id);break;case'goal-detail':goalDetail(id);break;case'delete-goal':deleteEntity('goal',id);break;case'goal-transaction':{const g=data.goals.find(x=>x.id===id);txForm('',{goalId:id,type:g.type==='saving'?'income':'expense',title:g.name,category:g.type==='saving'?(data.categories.find(c=>c.income)?.id||data.categories[0].id):data.categories[0].id});break;}case'add-recurring':recurringForm();break;case'delete-recurring':deleteEntity('recurring',id);break;case'settle-recurring':{const r=data.recurring.find(r=>r.id===id);confirmAction(t('支付本期账单？','Pay this occurrence?'),`${esc(r.title)} · ${r.next} · ${fmt(r.amount,acc(r.account).currency)}<br>${t('记账日期为今天，下一期按原周期推进。','Recorded today; the next due date advances by one period.')}`,()=>persist(d=>C.settleRecurring(d,id),t('已记账，账单推进到下一期','Recorded; next occurrence scheduled')));break;}case'add-debt':debtForm();break;case'repay':repayForm(id);break;case'delete-debt':deleteEntity('debt',id);break;case'debt-detail':{const d=data.debts.find(d=>d.id===id);modal(esc(d.name),`<p class="info">${t('本金','Principal')} ${fmt(d.amount,d.currency)} · ${t('尚余','Remaining')} ${fmt(C.debtRemaining(data,d),d.currency)}<br>${esc(d.notes)}</p>${txList(C.filtered(data).filter(t=>t.debtId===id))}<div class="modal-footer">${btn(t('删除借贷及关联交易','Delete loan and its transactions'),'delete-debt','trash','danger',`data-id="${esc(id)}"`)}</div>`);break;}case'transfer':if(data.accounts.length<2){notify(t('请先创建第二个账户','Create a second account first'));accountForm();}else txForm('',{type:'transfer',account:id||data.accounts[0].id,title:t('账户转账','Account transfer')});break;case'account-transactions':filters={account:id};query='';nav('transactions');break;case'prev-month':month=C.shift(month+'-01','monthly',-1).slice(0,7);render();break;case'next-month':month=C.shift(month+'-01','monthly',1).slice(0,7);render();break;case'month':modal(t('选择月份','Choose month'),`<form id="month-form">${field(t('月份','Month'),input('month',month,'month','required'))}${formFooter()}</form>`);break;case'theme':persist(d=>d.settings.theme=document.documentElement.dataset.theme==='dark'?'light':'dark');break;case'settings':nav('settings');break;case'search':nav('transactions');$('#tx-search')?.focus();break;case'notifications':modal(t('待办提醒','Upcoming reminders'),upcomingPanel()+`<p class="info">${t('此处为打开应用时的本地提醒，不是系统后台推送。','These are in-app reminders, not background system notifications.')}</p>`);break;case'filters':filterForm();break;case'clear-filters':filters={};query='';selected.clear();render();break;case'batch':batch=!batch;selected.clear();render();break;case'select-all':C.filtered(data,{...filters,query}).forEach(x=>selected.add(x.id));render();break;case'delete-selected':if(!selected.size){notify(t('先选择交易','Select transactions first'));break;}if(data.transactions.some(x=>selected.has(x.id)&&x.debtId))throw Error(t('所选包含借贷记录，请从借贷详情管理。','Selection includes loan entries; manage them from loan details.'));confirmAction(t('删除所选交易？','Delete selected entries?'),`${selected.size} ${t('笔交易将被永久删除。','transactions will be permanently deleted.')}`,()=>{persist(d=>d.transactions=d.transactions.filter(x=>!selected.has(x.id)),t('已删除','Deleted'));selected.clear();});break;case'export-json':backup();break;case'export-csv':download(C.exportCSV(data),`cashew-transactions-${C.iso()}.csv`,'text/csv;charset=utf-8');break;case'csv-template':download('\uFEFFdate,title,type,amount,account,category,notes,tags,status,toAccount,toAmount\r\n'+[C.iso(),'Example','expense','12.50',acc(data.accounts[0].id).name,data.categories[0].name,'','demo','paid','',''].map(x=>'"'+String(x).replaceAll('"','""')+'"').join(','),'cashew-template.csv','text/csv;charset=utf-8');break;case'import-json':chooseImport('json');break;case'import-csv':chooseImport('csv');break;case'raw-backup':download(localStorage.getItem(C.KEY)||'','cashew-raw-recovery.json');break;case'customize':customize();break;case'rates':rates();break;case'more':more();break;case'add-rule':modal(t('自动分类规则','Automatic title rule'),`<form id="rule-form">${field(t('名称包含的关键词','Title contains'),input('title','','text','required maxlength="120"'))}${field(t('自动归入分类','Assign category'),select('category',categoryOptions(),data.categories[0].id))}${formFooter()}</form>`);break;case'delete-rule':deleteEntity('rule',id);break;case'widget-up':{const r=b.closest('[data-widget]');if(r.previousElementSibling)r.parentNode.insertBefore(r,r.previousElementSibling);break;}case'widget-down':{const r=b.closest('[data-widget]');if(r.nextElementSibling)r.parentNode.insertBefore(r.nextElementSibling,r);break;}case'remove-attachment':attachments.splice(Number(b.dataset.index),1);$('#receipt-list').innerHTML=attachmentList();break;case'start-blank':if(persist(d=>d.setup=true))close();break;case'start-demo':if(persist(d=>Object.assign(d,C.demo())))close();break;case'load-demo':case'reset':confirmAction(a==='load-demo'?t('载入示例账本？','Load demo ledger?'):t('新建空白账本？','Start an empty ledger?'),t('这会替换当前所有记录。请先导出 JSON 备份。','This replaces all current records. Export a JSON backup first.'),()=>{persist(d=>{const fresh=a==='load-demo'?C.demo():C.defaults();fresh.setup=true;Object.assign(d,fresh);});selectedAccount='';nav('home');});break;case'cloud-push':await cloudPush();break;case'cloud-pull':await cloudPull();break;}}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-nav]');if(!b)return;try{if(b.dataset.action)await action(b.dataset.action,b);else if(b.dataset.nav){close();nav(b.dataset.nav);}else if(b.dataset.modalNav){close();nav(b.dataset.modalNav);}else if('account'in b.dataset){selectedAccount=b.dataset.account;render();}else if(b.dataset.tx)showTx(b.dataset.tx);else if(b.dataset.budget)budgetDetail(b.dataset.budget);else if(b.dataset.goal)goalDetail(b.dataset.goal);else if(b.dataset.editCategory)categoryForm(b.dataset.editCategory);else if(b.dataset.editRecurring)recurringForm(b.dataset.editRecurring);else if('homeType'in b.dataset){homeType=b.dataset.homeType;render();}else if(b.dataset.stats){statsType=b.dataset.stats;render();}else if(b.dataset.categoryFilter){filters={...monthPeriod(),category:b.dataset.categoryFilter,account:selectedAccount,type:page==='analysis'?statsType:'expense'};query='';nav('transactions');}else if(b.dataset.dateFilter){filters={start:b.dataset.dateFilter,end:b.dataset.dateFilter,account:selectedAccount};query='';nav('transactions');}else if(b.dataset.formType)updateTxType(b.dataset.formType);else if(b.dataset.pickIcon){$('#category-form').elements.icon.value=b.dataset.pickIcon;document.querySelectorAll('[data-pick-icon]').forEach(x=>x.classList.toggle('selected',x===b));}}catch(e){showError(e);}});
document.addEventListener('input',e=>{if(e.target.id==='tx-search'){query=e.target.value;selected.clear();const rows=C.filtered(data,{...filters,query});$('#tx-results').innerHTML=txList(rows,batch);$('#tx-count').textContent=rows.length+' '+t('笔交易','transactions');}if(e.target.name==='title'&&e.target.closest('#tx-form')){const title=e.target.value.toLowerCase(),rule=data.rules.find(r=>title.includes(r.title.toLowerCase())),same=data.transactions.find(t=>t.title.toLowerCase()===title);if(rule||same){const c=cat(rule?.category||same.category);if(c){$('#tx-form').elements.category.value=c.id;if($('#tx-form').elements.type.value!=='transfer')updateTxType(c.income?'income':'expense');}}}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.id==='filter-account'||el.id==='filter-type'){filters[el.id.slice(7)]=el.value;selected.clear();render();}if(el.dataset.selectTx){el.checked?selected.add(el.dataset.selectTx):selected.delete(el.dataset.selectTx);}if(el.name==='account'&&el.closest('#tx-form'))$('#amount-currency').textContent=acc(el.value)?.currency;if(el.name==='category'&&el.closest('#tx-form')){const c=cat(el.value);if(c&&$('#tx-form').elements.type.value!=='transfer')updateTxType(c.income?'income':'expense');}if(el.id==='receipt-file'&&el.files[0]){const f=el.files[0];if(f.size>2*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error(t('请选择 2 MB 以内的 PNG/JPG/WebP 图片','Choose a PNG/JPG/WebP under 2 MB'));if(attachments.length>=3)throw Error(t('每筆最多三张附件','Up to 3 attachments per transaction'));const result=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});attachments.push({name:f.name.slice(0,200),data:result});$('#receipt-list').innerHTML=attachmentList();}if(el.id==='import-file'&&el.files[0]){const file=el.files[0];if(file.size>25*1024*1024)throw Error(t('备份过大（最大 25 MB）','Backup too large (25 MB maximum)'));const text=await file.text();if(el.dataset.kind==='json'){const imported=C.validate(JSON.parse(text));confirmAction(t('恢复完整备份？','Restore full backup?'),`${imported.transactions.length} ${t('笔交易，将替换当前全部数据。','transactions. All current data will be replaced.')}`,()=>{const old=loadError;loadError=null;if(!persist(d=>Object.assign(d,imported),t('已恢复备份','Backup restored'),!!old))loadError=old;selectedAccount='';render();});}else{const test=structuredClone(data),count=C.importCSV(test,text);confirmAction(t('导入 CSV？','Import CSV?'),`${count} ${t('笔交易将追加到现有账本。重复导入会产生重复记录。','entries will be appended. Importing again creates duplicates.')}`,()=>persist(d=>C.importCSV(d,text),t('CSV 已导入','CSV imported')));}}}catch(e){showError(e);}});
const upsert=(d,key,obj)=>{const i=d[key].findIndex(x=>x.id===obj.id);if(i<0)d[key].push(obj);else d[key][i]=obj;};
const signedMoney=s=>{const n=Number(s);if(!Number.isFinite(n))throw Error(t('请输入有效金额','Enter a valid amount'));return (n<0?-1:1)*C.money(String(s).replace(/^[-+]/,''));};
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,f=new FormData(form),v=n=>String(f.get(n)||'').trim(),id=form.dataset.id||C.uid();try{if(loadError&&form.id!=='cloud-form')throw Error(t('请先恢复有效备份','Restore a valid backup first'));switch(form.id){case'tx-form':{const type=v('type'),amount=C.money(v('amount')),account=v('account'),to=v('toAccount');if(type==='transfer'&&account===to)throw Error(t('转出与转入账户不能相同','Choose two different accounts'));const old=data.transactions.find(x=>x.id===id);const x={...old,id,type,amount,account,title:v('title'),date:v('date'),category:type==='transfer'?'':v('category'),notes:v('notes'),tags:v('tags').split(/[,，]/).map(x=>x.trim()).filter(Boolean),status:v('status'),budgetIds:type==='transfer'?[]:f.getAll('budgetIds'),goalId:type==='transfer'?'':v('goalId'),attachments:structuredClone(attachments)};if(type==='transfer'){x.toAccount=to;x.toAmount=v('toAmount')?C.money(v('toAmount')):C.convert(data,amount,acc(account).currency,acc(to).currency);}else{delete x.toAccount;delete x.toAmount;}if(persist(d=>upsert(d,'transactions',x),t('交易已保存','Transaction saved')))close();break;}case'budget-form':{const limits={};data.categories.forEach(c=>{if(v('limit-'+c.id))limits[c.id]=C.money(v('limit-'+c.id));});const b={id,name:v('name'),amount:C.money(v('amount')),currency:v('currency'),period:v('period'),start:v('start'),end:v('end'),mode:v('mode'),color:v('color'),categories:f.getAll('categories'),accounts:f.getAll('accounts'),limits};if(b.start>b.end)throw Error(t('结束日期不能早于开始日期','End date must follow start date'));if(persist(d=>upsert(d,'budgets',b),t('预算已保存','Budget saved')))close();break;}case'account-form':{const old=acc(id),a={id,name:v('name'),currency:v('currency')||old?.currency,opening:signedMoney(v('opening')),color:v('color'),icon:v('icon')};if(data.accounts.some(x=>x.id!==id&&x.name===a.name))throw Error(t('账户名称已存在','Account name already exists'));if(persist(d=>upsert(d,'accounts',a),t('账户已保存','Account saved')))close();break;}case'category-form':{const c={id,name:v('name'),color:v('color'),icon:v('icon'),income:v('income')==='yes'};if(data.categories.some(x=>x.id!==id&&x.name===c.name))throw Error(t('分类名称已存在','Category name already exists'));if(persist(d=>upsert(d,'categories',c),t('分类已保存','Category saved')))close();break;}case'goal-form':{const g={id,name:v('name'),amount:C.money(v('amount')),initial:signedMoney(v('initial')),currency:v('currency'),type:v('type'),color:v('color'),icon:v('icon'),date:v('date')};if(persist(d=>upsert(d,'goals',g),t('目标已保存','Goal saved')))close();break;}case'recurring-form':{const old=data.recurring.find(x=>x.id===id),r={id,title:v('title'),amount:C.money(v('amount')),type:v('type'),account:v('account'),category:v('category'),next:v('next'),anchor:old&&old.next===v('next')?old.anchor:Number(v('next').slice(-2)),frequency:v('frequency'),notes:v('notes'),tags:old?.tags||[],active:v('active')==='yes'};if(persist(d=>upsert(d,'recurring',r),t('周期账单已保存','Recurring bill saved')))close();break;}case'debt-form':{const amount=C.money(v('amount')),account=v('account'),debt={id,name:v('name'),amount,account,currency:acc(account).currency,type:v('type'),date:v('date'),due:v('due'),notes:v('notes')};if(persist(d=>{d.debts.push(debt);d.transactions.push({id:C.uid(),debtId:id,debtRole:'principal',title:debt.name+' · '+t('本金','Principal'),amount,account,type:debt.type==='lent'?'expense':'income',date:debt.date,category:v('category'),status:'paid',tags:[],notes:debt.notes,budgetIds:[],goalId:'',attachments:[]});},t('借贷已保存','Loan recorded')))close();break;}case'repay-form':{const debt=data.debts.find(x=>x.id===id),amount=C.money(v('amount'));if(amount>C.debtRemaining(data,debt))throw Error(t('金额超过剩余本金','Payment exceeds remaining principal'));if(persist(d=>d.transactions.push({id:C.uid(),debtId:id,debtRole:'repayment',title:debt.name+' · '+t('还款','Repayment'),amount,account:debt.account,type:debt.type==='lent'?'income':'expense',date:v('date'),category:d.transactions.find(x=>x.debtId===id&&x.debtRole==='principal').category,status:'paid',tags:[],notes:'',budgetIds:[],goalId:'',attachments:[]}),t('还款已记录','Payment recorded')))close();break;}case'filters-form':{if(v('start')&&v('end')&&v('start')>v('end'))throw Error(t('日期范围无效','Invalid date range'));const min=v('min')?C.money(v('min')):0,max=v('max')?C.money(v('max')):0;if(min&&max&&min>max)throw Error(t('金额范围无效','Invalid amount range'));filters={...filters,start:v('start'),end:v('end'),category:v('category'),status:v('status'),min,max};selected.clear();close();render();break;}case'month-form':month=v('month');close();render();break;case'settings-form':persist(d=>Object.assign(d.settings,{name:v('name'),theme:v('theme'),accent:v('accent'),language:v('language'),currency:v('currency')}),t('设置已保存','Preferences saved'));break;case'widgets-form':if(persist(d=>d.settings.widgets=f.getAll('widget'),t('首页已更新','Home updated')))close();break;case'rates-form':if(persist(d=>Object.keys(d.settings.rates).forEach(c=>d.settings.rates[c]=Number(v(c))),t('汇率已更新','Rates updated')))close();break;case'rule-form':if(persist(d=>d.rules.push({id,title:v('title'),category:v('category')}),t('规则已保存','Rule saved')))close();break;case'cloud-form':await cloudConnect(form);break;case'split-form':{const total=C.money(v('total')),names=v('people').split('\n').map(s=>s.trim()).filter(Boolean),payer=v('payer'),currency=v('currency');if(names.length<2||names.length>50||new Set(names).size!==names.length||!names.includes(payer))throw Error(t('需要 2–50 个不重复的名字，付款人必须在名单中。','Use 2–50 unique names, including the payer.'));const each=Math.floor(total/names.length),remainder=total%names.length;$('#split-error').textContent='';$('#split-result').innerHTML=`<div class="section-heading"><h3>${t('分摊结果','Settlement')}</h3><small>${fmt(total,currency)}</small></div>`+names.map((n,i)=>`<div class="setting-row"><div class="copy"><b>${esc(n)}</b><p>${n===payer?t('付款人自己的份额','Payer’s own share'):t('需转给 ','Owes ')+esc(payer)}</p></div><strong>${fmt(each+(i<remainder?1:0),currency)}</strong></div>`).join('');break;}}}catch(e){if(form.id==='split-form')$('#split-error').textContent=e.message;else showError(e);}});
window.addEventListener('storage',e=>{if(e.key===C.KEY){try{data=storage.load();close();render();notify(t('已载入另一标签页的更改','Loaded changes from another tab'));}catch(err){notify(err.message);}}});
window.addEventListener('hashchange',()=>{const target=location.hash.slice(1);if(labels[target]&&target!==page){page=target;render();}});
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>{if(data.settings.theme==='system')applyTheme();});
document.addEventListener('keydown',e=>{if(!$('#modal').open&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)){if(!loadError&&e.key==='n'){e.preventDefault();txForm();}if(e.key==='/'){e.preventDefault();nav('transactions');$('#tx-search').focus();}}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
const initial=location.hash.slice(1);if(labels[initial])page=initial;render();if(!data.setup&&!loadError)welcome();
const params=new URLSearchParams(location.search);if(data.setup&&params.get('add')==='1'){txForm('',{title:(params.get('title')||'').slice(0,120),amount:(()=>{try{return C.money(params.get('amount')||'0');}catch{return 0;}})(),type:params.get('type')==='income'?'income':'expense'});}
if(location.protocol!=='file:'&&'serviceWorker'in navigator&&!window.CASHEW_SINGLE_FILE)navigator.serviceWorker.register('./sw.js').catch(()=>{});
})();
